begin;
select plan(19);
insert into auth.users(id,is_anonymous) values('f2000000-0000-4000-8000-000000000001',true),('f2000000-0000-4000-8000-000000000002',true),('f2000000-0000-4000-8000-000000000003',true);
set local role authenticated;
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"is_anonymous":true}',true);
select public.create_code_band('Repertoire','Leader','기타','1234','112233');
select set_config('test.rep.band',public.current_band_identity()->>'band_id',true);
select set_config('test.rep.code',public.band_login_settings()->>'code',true);
-- Since 023 only members who saved a date attend it: the leader opts in to the plan days used below.
select public.save_band_availability((select jsonb_agg(jsonb_build_object('date',((now() at time zone 'Asia/Seoul')::date+n)::text)) from generate_series(1,4) n));
select set_config('test.rep.song',public.add_song(current_setting('test.rep.band')::uuid,'Chosen song','Artist')::text,true);
select lives_ok($$select public.set_song_confirmation(current_setting('test.rep.song')::bigint,true)$$,'leader can directly decide a repertoire song');
select ok((public.band_planning_context()->'songs'->0->>'confirmedAt') is not null,'context exposes confirmation');
select set_config('test.rep.version',public.band_planning_context()->>'version',true);
select public.set_song_confirmation(current_setting('test.rep.song')::bigint,true);
select is(public.band_planning_context()->>'version',current_setting('test.rep.version'),'reconfirm is idempotent');
select set_config('test.rep.plan',public.save_rehearsal_plan(current_setting('test.rep.band')::uuid,(now() at time zone 'Asia/Seoul')::date+1,array[current_setting('test.rep.song')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false)::text,true);
select is((select title_snapshot from public.confirmed_plan_songs where plan_id=current_setting('test.rep.plan')::uuid),'Chosen song','confirmed song selectable without recommendation prerequisites');
select public.delete_live_plan(current_setting('test.rep.plan')::uuid,1);
select ok((select confirmed_at is not null from public.songs where id=current_setting('test.rep.song')::bigint),'deleting plan retains repertoire confirmation');
select lives_ok($$select public.save_rehearsal_plan(current_setting('test.rep.band')::uuid,(now() at time zone 'Asia/Seoul')::date+2,array[current_setting('test.rep.song')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false)$$,'same song can be chosen again in a new plan');
select set_config('test.rep.plan',(select id::text from public.confirmed_plans where band_id=current_setting('test.rep.band')::uuid limit 1),true);
select lives_ok($$select public.set_song_confirmation(current_setting('test.rep.song')::bigint,false)$$,'leader removes from repertoire');
select is((select count(*)::int from public.songs where id=current_setting('test.rep.song')::bigint),1,'removing confirmation keeps candidate');
select is((select count(*)::int from public.confirmed_plan_songs where plan_id=current_setting('test.rep.plan')::uuid),1,'removing confirmation preserves plan snapshot');
select throws_ok($$select public.save_rehearsal_plan(current_setting('test.rep.band')::uuid,(now() at time zone 'Asia/Seoul')::date+3,array[current_setting('test.rep.song')::bigint],(public.band_planning_context()->>'version')::bigint,null,null,false)$$,'P0001','SONG_NOT_ELIGIBLE','unconfirmed candidate still needs original recommendation conditions');
select lives_ok($$select public.save_rehearsal_plan(current_setting('test.rep.band')::uuid,(now() at time zone 'Asia/Seoul')::date+4,array[current_setting('test.rep.song')::bigint],(public.band_planning_context()->>'version')::bigint,current_setting('test.rep.plan')::uuid,1,false)$$,'retained plan song remains editable after unconfirmation');
select throws_ok($$select public.set_song_confirmation(current_setting('test.rep.song')::bigint,null)$$,'P0001','INVALID_INPUT','null state rejected');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000002',true);
select public.begin_band_access(current_setting('test.rep.code'),'1234');select public.register_band_profile('Member','베이스','246810');
select throws_ok($$select public.set_song_confirmation(current_setting('test.rep.song')::bigint,true)$$,'P0001','FORBIDDEN','member cannot confirm');
select throws_ok($$select public.set_song_confirmation(current_setting('test.rep.song')::bigint,false)$$,'P0001','FORBIDDEN','member cannot remove confirmation');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000003',true);
select public.create_code_band('Other','Other leader','기타','1234','556677');
select throws_ok($$select public.set_song_confirmation(current_setting('test.rep.song')::bigint,true)$$,'P0001','FORBIDDEN','other band leader cannot confirm');
select ok(not has_function_privilege('anon','public.set_song_confirmation(bigint,boolean)','execute'),'anon cannot call confirmation');
select ok(not has_column_privilege('authenticated','public.songs','confirmed_at','UPDATE'),'direct writes cannot bypass leader RPC');
select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
select public.vote_band_song(current_setting('test.rep.song')::bigint,'yes',null);
select public.set_song_confirmation(current_setting('test.rep.song')::bigint,true);select public.set_song_confirmation(current_setting('test.rep.song')::bigint,false);
select is((select count(*)::int from public.band_song_votes where song_id=current_setting('test.rep.song')::bigint),1,'confirm and remove preserve votes');
select throws_ok($$select public.set_song_confirmation(9223372036854775807,true)$$,'P0001','SONG_NOT_FOUND','missing song rejected');
select * from finish();rollback;
